// Replay harness and snapshot verification.
//
// IMPORTANT about what these tests establish: the committed data set is SYNTHETIC,
// generated by scripts/make_synthetic_lobster.py. A passing verification here
// shows that the C++ replay agrees with that script. It is not independent
// verification against LOBSTER. See docs/TESTING.md for which verification has
// actually been run.
#include <gtest/gtest.h>

#include <chrono>
#include <fstream>
#include <sstream>
#include <string>

#include "lobkit/book/invariants.hpp"
#include "lobkit/md/lobster.hpp"
#include "lobkit/md/replay.hpp"
#include "reference_book.hpp"
#include "workload.hpp"

using namespace lobkit;
using namespace lobkit::md;

namespace {

std::string slurp(const std::string& name) {
  std::ifstream f(std::string(LOBKIT_DATA_DIR) + "/" + name, std::ios::binary);
  std::stringstream ss;
  ss << f.rdbuf();
  return ss.str();
}

BookConfig lobster_cfg(std::uint32_t levels = 4096) {
  BookConfig c;
  c.tick_size = 100;
  c.base_price = 900000;  // $90.00; the synthetic data lives near $100
  c.num_levels = levels;
  c.max_orders = 1 << 16;
  return c;
}

struct VerifyRun {
  VerifyResult res;
  ReplayCounters counters;
  BookStats stats;
};

VerifyRun verify(const std::string& msgs, const std::string& rows, std::uint32_t levels,
                 BookConfig cfg = lobster_cfg()) {
  Engine<NullSink> eng(cfg);
  lobster::MessageReader mr(msgs);
  lobster::BookRowReader br(rows, levels);
  VerifyRun r;
  r.res = replay_verify(eng, mr, br, r.counters);
  r.stats = eng.book().stats();
  return r;
}

}  // namespace

TEST(Replay, PlainReplayCountsEveryMessageClass) {
  const std::string text = slurp("SYNTH_lobster_1000_message_10.csv");
  Engine<NullSink> eng(lobster_cfg());
  lobster::MessageReader rd(text);
  ReplayCounters c;
  const RunResult r = replay(eng, rd, c);
  EXPECT_EQ(r.status, ParseStatus::End);
  EXPECT_EQ(c.messages, 1000u);
  EXPECT_EQ(c.adds + c.reduces + c.deletes + c.executes + c.hidden_executions + c.halts, 1000u);
  EXPECT_GT(c.hidden_executions, 0u);  // type 5 is counted separately...
  EXPECT_GT(c.hidden_shares, 0u);
  EXPECT_GT(c.halts, 0u);  // ...and so are halts
  EXPECT_EQ(eng.book().stats().feed_problems(), 0u);
  EXPECT_EQ(eng.book().stats().trades, c.executes);  // one trade event per displayed execution
  EXPECT_FALSE(check_invariants(eng.book()).has_value());
}

TEST(Replay, HiddenExecutionsAndHaltsDoNotTouchTheBook) {
  Engine<NullSink> eng(lobster_cfg());
  lobster::MessageReader rd(
      "1.0,1,10,100,1000000,1\n2.0,5,0,50,1000000,1\n3.0,7,0,0,-1,-1\n4.0,6,0,10,1000100,1\n");
  ReplayCounters c;
  ASSERT_EQ(replay(eng, rd, c).status, ParseStatus::End);
  EXPECT_EQ(c.hidden_executions, 1u);
  EXPECT_EQ(c.hidden_shares, 50u);
  EXPECT_EQ(c.halts, 1u);
  EXPECT_EQ(c.cross_trades, 1u);
  EXPECT_EQ(eng.book().depth_at(1000000), 100u);
  EXPECT_EQ(eng.book().stats().trades, 0u);
}

TEST(Replay, PlainReplayReportsProblemsAndKeepsGoing) {
  Engine<NullSink> eng(lobster_cfg());
  lobster::MessageReader rd(
      "1.0,3,999,5,1000000,1\n"   // delete of an unknown order
      "2.0,1,1,10,50,1\n"         // price far below the band
      "3.0,1,2,10,1000050,1\n"    // off tick
      "4.0,1,3,10,1000000,1\n"    // fine
      "5.0,4,3,99,1000000,1\n");  // executes more than is left
  ReplayCounters c;
  ASSERT_EQ(replay(eng, rd, c).status, ParseStatus::End);
  const BookStats& s = eng.book().stats();
  EXPECT_EQ(s.reject_count(RejectReason::UnknownOrderId), 1u);
  EXPECT_EQ(s.reject_count(RejectReason::PriceOutOfBand), 1u);
  EXPECT_EQ(s.reject_count(RejectReason::PriceOffTick), 1u);
  EXPECT_EQ(s.feed_exec_overflow, 1u);
  EXPECT_EQ(s.feed_problems(), 4u);
  EXPECT_EQ(c.messages, 5u);
}

TEST(Replay, ParseErrorStopsTheRunWithItsCode) {
  Engine<NullSink> eng(lobster_cfg());
  lobster::MessageReader rd("1.0,1,1,10,1000000,1\ngarbage\n2.0,1,2,10,1000000,1\n");
  ReplayCounters c;
  const RunResult r = replay(eng, rd, c);
  EXPECT_EQ(r.status, ParseStatus::BadTimestamp);
  EXPECT_EQ(c.messages, 1u);
  EXPECT_EQ(rd.line_number(), 2u);
}

TEST(Replay, LimitStopsEarly) {
  Engine<NullSink> eng(lobster_cfg());
  const std::string text = slurp("SYNTH_lobster_1000_message_10.csv");
  lobster::MessageReader rd(text);
  ReplayCounters c;
  EXPECT_EQ(replay(eng, rd, c, nullptr, 100).status, ParseStatus::End);
  EXPECT_EQ(c.messages, 100u);
}

TEST(Replay, ItchReplaceOfUnknownOrderIsCounted) {
  Engine<NullSink> eng(lobster_cfg());
  ReplayCounters c;
  FeedMsg m{};
  m.type = FeedType::Replace;
  m.id = 5;
  m.new_id = 6;
  m.price = 1000000;
  m.qty = 10;
  apply_feed(eng, c, m);
  EXPECT_EQ(c.replace_unknown, 1u);
  EXPECT_EQ(eng.book().stats().reject_count(RejectReason::UnknownOrderId), 1u);
  EXPECT_EQ(eng.book().live_orders(),
            0u);  // the new order is not created from a replace of nothing
}

// ---- verification ----------------------------------------------------------------

TEST(Verify, SyntheticDataSelfConsistency) {
  // Passing this proves the C++ replay agrees with the Python generator, nothing more.
  const VerifyRun r = verify(slurp("SYNTH_lobster_1000_message_10.csv"),
                             slurp("SYNTH_lobster_1000_orderbook_10.csv"), 10);
  ASSERT_TRUE(r.res.ok) << to_string(r.res.div.reason) << " at " << r.res.div.message_index;
  EXPECT_EQ(r.res.verified, 1000u);
  EXPECT_EQ(r.res.message_status, ParseStatus::End);
  EXPECT_EQ(r.stats.feed_problems(), 0u);
}

TEST(Verify, ReportsTheFirstRowMismatchWithExpectedAndActual) {
  std::string rows = slurp("SYNTH_lobster_1000_orderbook_10.csv");
  const std::string msgs = slurp("SYNTH_lobster_1000_message_10.csv");
  // Corrupt row 300 (0 based): bump the first ask size by one wherever it is non-dummy.
  std::size_t pos = 0;
  for (int i = 0; i < 300; ++i) pos = rows.find('\n', pos) + 1;
  const std::size_t eol = rows.find('\n', pos);
  std::string row = rows.substr(pos, eol - pos);
  // Find a level that exists: first field is the ask price; if dummy, change bid size instead.
  const std::size_t c1 = row.find(',');
  const std::size_t c2 = row.find(',', c1 + 1);
  const std::size_t c3 = row.find(',', c2 + 1);
  const std::size_t c4 = row.find(',', c3 + 1);
  ASSERT_NE(c4, std::string::npos);
  // Replace the size at position 2 (field index 1) with a value that cannot match.
  row.replace(c1 + 1, c2 - c1 - 1, "123456789");
  rows.replace(pos, eol - pos, row);

  const VerifyRun r = verify(msgs, rows, 10);
  ASSERT_FALSE(r.res.ok);
  EXPECT_EQ(r.res.div.reason, DivergenceReason::RowMismatch);
  EXPECT_EQ(r.res.div.message_index, 300u);
  EXPECT_EQ(r.res.verified, 300u);  // everything before it matched
  EXPECT_EQ(r.res.div.expected_ask[0].size, 123456789);
  EXPECT_NE(r.res.div.actual_ask[0].size, 123456789);
  EXPECT_EQ(r.res.div.levels, 10u);
  EXPECT_GT(r.res.div.line_number, 0u);
  EXPECT_NE(std::string(r.res.div.line).find(','), std::string::npos);
}

TEST(Verify, UnknownOrderIsAHardFailure) {
  const VerifyRun r = verify("1.0,3,999,5,1000000,1\n", "9999999999,0,-9999999999,0\n", 1);
  ASSERT_FALSE(r.res.ok);
  EXPECT_EQ(r.res.div.reason, DivergenceReason::FeedProblem);
  EXPECT_EQ(r.res.div.reject, RejectReason::UnknownOrderId);
  EXPECT_EQ(r.res.div.message_index, 0u);
}

TEST(Verify, OutOfBandAndOffTickAreHardFailures) {
  VerifyRun r = verify("1.0,1,1,10,50,1\n", "9999999999,0,-9999999999,0\n", 1);
  ASSERT_FALSE(r.res.ok);
  EXPECT_EQ(r.res.div.reason, DivergenceReason::FeedProblem);
  EXPECT_EQ(r.res.div.reject, RejectReason::PriceOutOfBand);
  r = verify("1.0,1,1,10,1000050,1\n", "9999999999,0,-9999999999,0\n", 1);
  ASSERT_FALSE(r.res.ok);
  EXPECT_EQ(r.res.div.reject, RejectReason::PriceOffTick);
}

TEST(Verify, AnomalyIsAHardFailure) {
  // The execute is larger than the order: exec_overflow counts as an anomaly.
  const std::string rows = "9999999999,0,1000000,10\n9999999999,0,-9999999999,0\n";
  const VerifyRun r = verify("1.0,1,1,10,1000000,1\n2.0,4,1,99,1000000,1\n", rows, 1);
  ASSERT_FALSE(r.res.ok);
  EXPECT_EQ(r.res.div.reason, DivergenceReason::FeedProblem);
  EXPECT_EQ(r.res.div.message_index, 1u);
  EXPECT_EQ(r.res.div.anomalies_delta, 1u);
  EXPECT_EQ(r.res.verified, 1u);
}

TEST(Verify, MessageThatDisagreesWithItsOrderIsAFieldMismatch) {
  const std::string rows = "9999999999,0,1000000,10\n";
  // Order 1 is a buy at 1000000; the second message calls it a sell order.
  const VerifyRun r = verify("1.0,1,1,10,1000000,1\n2.0,3,1,10,1000000,-1\n", rows + rows, 1);
  ASSERT_FALSE(r.res.ok);
  EXPECT_EQ(r.res.div.reason, DivergenceReason::FieldMismatch);
  EXPECT_EQ(r.res.div.message_index, 1u);
  const VerifyRun r2 =
      verify("1.0,1,1,10,1000000,1\n2.0,3,1,10,1000100,1\n", rows + rows, 1);  // wrong price
  EXPECT_EQ(r2.res.div.reason, DivergenceReason::FieldMismatch);
}

TEST(Verify, MissingAndMalformedRowsAreReported) {
  VerifyRun r =
      verify("1.0,1,1,10,1000000,1\n2.0,1,2,10,1000000,1\n", "9999999999,0,1000000,10\n", 1);
  ASSERT_FALSE(r.res.ok);
  EXPECT_EQ(r.res.div.reason, DivergenceReason::RowsExhausted);
  EXPECT_EQ(r.res.div.message_index, 1u);
  r = verify("1.0,1,1,10,1000000,1\n", "oops\n", 1);
  ASSERT_FALSE(r.res.ok);
  EXPECT_EQ(r.res.div.reason, DivergenceReason::RowParseError);
}

TEST(Verify, MessageParseErrorIsReported) {
  const VerifyRun r =
      verify("1.0,1,1,10,1000000,1\nnot a message\n", "9999999999,0,1000000,10\n", 1);
  ASSERT_FALSE(r.res.ok);
  EXPECT_EQ(r.res.div.reason, DivergenceReason::MessageParseError);
  EXPECT_EQ(r.res.div.message_index, 1u);
  EXPECT_EQ(r.res.message_status, ParseStatus::BadTimestamp);
}

TEST(Verify, MoreRowsThanMessagesIsNotAFailure) {
  // Surplus rows are ignored; the verification covers every message that exists.
  const std::string row = "9999999999,0,1000000,10\n";
  const VerifyRun r = verify("1.0,1,1,10,1000000,1\n", row + row, 1);
  EXPECT_TRUE(r.res.ok);
  EXPECT_EQ(r.res.verified, 1u);
}

TEST(Verify, HiddenExecutionsMustLeaveTheRowUnchanged) {
  const std::string row1 = "9999999999,0,1000000,10\n";
  const std::string changed = "9999999999,0,1000000,7\n";
  EXPECT_TRUE(verify("1.0,1,1,10,1000000,1\n2.0,5,0,3,1000000,1\n", row1 + row1, 1).res.ok);
  EXPECT_FALSE(verify("1.0,1,1,10,1000000,1\n2.0,5,0,3,1000000,1\n", row1 + changed, 1).res.ok);
}

TEST(Verify, LimitCapsTheNumberOfMessages) {
  Engine<NullSink> eng(lobster_cfg());
  const std::string msgs = slurp("SYNTH_lobster_1000_message_10.csv");
  const std::string rows = slurp("SYNTH_lobster_1000_orderbook_10.csv");
  lobster::MessageReader mr(msgs);
  lobster::BookRowReader br(rows, 10);
  ReplayCounters c;
  const VerifyResult v = replay_verify(eng, mr, br, c, 250);
  EXPECT_TRUE(v.ok);
  EXPECT_EQ(v.verified, 250u);
}

// ---- top_levels, the query verification depends on -------------------------------

TEST(TopLevels, MatchesTheReferenceBookDepthOnRandomBooks) {
  using namespace lobkit::testing;
  BookConfig cfg;
  cfg.tick_size = 100;
  cfg.base_price = 100000;
  cfg.num_levels = 1024;
  cfg.max_orders = 4096;
  Engine<NullSink> eng(cfg);
  ReferenceBook ref(cfg);
  WorkloadParams p;
  p.seed = 77;
  p.n = 20000;
  p.feed_ops = true;
  const auto ops = make_workload(p);
  for (std::size_t i = 0; i < ops.size(); ++i) {
    apply(eng, ops[i]);
    switch (ops[i].kind) {
      case Op::Submit:
        ref.submit(ops[i].order);
        break;
      case Op::Cancel:
        ref.cancel(ops[i].id, ops[i].ts);
        break;
      case Op::Modify:
        ref.modify(ops[i].mod);
        break;
      case Op::FeedAdd:
        ref.feed_add(ops[i].order.id, ops[i].order.side, ops[i].order.price, ops[i].order.qty,
                     ops[i].ts);
        break;
      case Op::FeedReduce:
        ref.feed_reduce(ops[i].id, ops[i].qty, ops[i].ts);
        break;
      case Op::FeedDelete:
        ref.feed_delete(ops[i].id, ops[i].ts);
        break;
      case Op::FeedExecute:
        ref.feed_execute(ops[i].id, ops[i].qty, ops[i].ts);
        break;
    }
    ref.events.clear();
    if (i % 53 != 0) continue;
    for (Side side : {Side::Bid, Side::Ask}) {
      Book<NullSink>::LevelView v[7];
      const std::size_t k = eng.book().top_levels(side, v, 7);
      // Expected: walk the grid from the touch in the right direction.
      std::size_t expect = 0;
      for (int t = 0; t < 1024; ++t) {
        const int tick = side == Side::Bid ? 1023 - t : t;
        const Price px = cfg.base_price + cfg.tick_size * tick;
        // The reference reports total depth at a price. A price belongs to the
        // bid side iff it is at or below the best bid (the book is uncrossed).
        const bool on_side = side == Side::Bid ? (ref.has_bid() && px <= ref.best_bid())
                                               : (ref.has_ask() && px >= ref.best_ask());
        const Qty d = on_side ? ref.depth_at(px) : 0;
        if (d == 0) continue;
        ASSERT_LT(expect, k) << "engine reports fewer levels, op " << i;
        EXPECT_EQ(v[expect].price, px) << i;
        EXPECT_EQ(v[expect].qty, d) << i;
        if (++expect == 7) break;
      }
      EXPECT_EQ(k, expect) << i;
    }
  }
}

// ---- pacing and grid helpers -------------------------------------------------------

TEST(Pacer, NeverReleasesEarlyAndScalesBySpeed) {
  using clk = std::chrono::steady_clock;
  // Messages 100 ms apart in feed time, replayed at 10x: 10 ms apart in wall time.
  Pacer p(10.0);
  const auto t0 = clk::now();
  p.wait_until(1'000'000'000);
  p.wait_until(1'100'000'000);
  p.wait_until(1'200'000'000);
  const auto el = std::chrono::duration<double, std::milli>(clk::now() - t0).count();
  EXPECT_GE(el, 19.5);   // two gaps of 10 ms; allow clock rounding only below
  EXPECT_LT(el, 400.0);  // generous upper bound: a loaded CI runner may oversleep
}

TEST(Pacer, AsFastAsPossibleDoesNotWait) {
  using clk = std::chrono::steady_clock;
  Engine<NullSink> eng(lobster_cfg());
  // Messages a full second apart in feed time.
  lobster::MessageReader rd("1.0,1,1,10,1000000,1\n2.0,1,2,10,1000000,1\n3.0,1,3,10,1000000,1\n");
  ReplayCounters c;
  const auto t0 = clk::now();
  replay(eng, rd, c);
  EXPECT_LT(std::chrono::duration<double>(clk::now() - t0).count(), 0.5);
}

TEST(Pacer, PacedReplayAppliesTheSameMessages) {
  Engine<NullSink> eng(lobster_cfg());
  lobster::MessageReader rd(
      "1.000,1,1,10,1000000,1\n1.005,1,2,10,1000100,-1\n1.010,4,1,4,1000000,1\n");
  ReplayCounters c;
  Pacer pacer(5.0);  // 10 ms of feed time becomes 2 ms
  const RunResult r = replay(eng, rd, c, &pacer);
  EXPECT_EQ(r.status, ParseStatus::End);
  EXPECT_EQ(c.messages, 3u);
  EXPECT_EQ(eng.book().depth_at(1000000), 6u);
  EXPECT_GE(r.seconds, 0.0019);
}

TEST(Grid, ScansPriceRangeAndCentersTheBand) {
  lobster::MessageReader rd(
      "1.0,1,1,1,5000000,1\n2.0,1,2,1,5100000,-1\n3.0,1,3,1,4900000,1\n4.0,3,1,1,5000000,1\n");
  Price lo = 0, hi = 0;
  ASSERT_TRUE(scan_price_range(rd, lo, hi));
  EXPECT_EQ(lo, 4900000);
  EXPECT_EQ(hi, 5100000);
  // The caller's reader was passed by value and is untouched.
  FeedMsg m;
  ASSERT_EQ(rd.next(m), ParseStatus::Ok);
  EXPECT_EQ(m.id, 1u);
  const Price base = suggest_base_price(lo, hi, 100, 4096);
  EXPECT_EQ(base % 100, 0);
  EXPECT_LE(base, lo);
  EXPECT_GE(base + 4096 * 100, hi);
  EXPECT_EQ(suggest_base_price(100, 200, 100, 1024), 0);  // never negative
  lobster::MessageReader empty("");
  EXPECT_FALSE(scan_price_range(empty, lo, hi));
}

TEST(MdNames, EveryStatusAndDivergenceReasonHasAName) {
  for (auto s : {ParseStatus::Ok, ParseStatus::End, ParseStatus::Truncated, ParseStatus::ZeroLength,
                 ParseStatus::BadLength, ParseStatus::BadField, ParseStatus::BadType,
                 ParseStatus::BadTimestamp, ParseStatus::Overflow, ParseStatus::BadLevelCount})
    EXPECT_STRNE(to_string(s), "?");
  for (auto r :
       {DivergenceReason::None, DivergenceReason::RowMismatch, DivergenceReason::FeedProblem,
        DivergenceReason::FieldMismatch, DivergenceReason::RowsExhausted,
        DivergenceReason::RowParseError, DivergenceReason::MessageParseError})
    EXPECT_STRNE(to_string(r), "?");
  EXPECT_STREQ(to_string(static_cast<ParseStatus>(200)), "?");
  EXPECT_STREQ(to_string(static_cast<DivergenceReason>(200)), "?");
}
